const cfg = $('Ingestion Config').first().json;
const f = $json;
return {
  json: { ...f, clinic_id: cfg.clinic_id, clinic_name: cfg.clinic_name, category: cfg.category,
    pinecone_index: cfg.pinecone_index, pinecone_namespace: cfg.pinecone_namespace, pinecone_host: cfg.pinecone_host,
    registry_sheet_id: cfg.registry_sheet_id },
  binary: $binary
};

const hasError = !!$json.error;
const hasContent = !!($binary && $binary.data && $binary.data.data && $binary.data.data.length > 0);
let reason = 'ok';
if (hasError) reason = 'download_failed';
else if (!hasContent) reason = 'empty_file';
return { json: { ...$json, _validation_reason: reason }, binary: $binary };

return { json: { registry_sheet_id: $json.registry_sheet_id, timestamp: $now.toISO(),
  google_drive_file_id: $json.id || $json.google_drive_file_id || '', source_document: $json.name || $json.source_document || 'unknown',
  error_type: 'download_failed', error_message: ($json.error && $json.error.message) || 'File download failed', stage: 'download' } };

return { json: { registry_sheet_id: $json.registry_sheet_id, timestamp: $now.toISO(),
  google_drive_file_id: $json.id || $json.google_drive_file_id || '', source_document: $json.name || $json.source_document || 'unknown',
  error_type: 'empty_file', error_message: 'Downloaded file has no content (0 bytes)', stage: 'download' } };

return { json: { registry_sheet_id: $json.registry_sheet_id, timestamp: $now.toISO(),
  google_drive_file_id: $json.id || $json.google_drive_file_id || '', source_document: $json.name || $json.source_document || 'unknown',
  error_type: 'unsupported_file_type', error_message: 'Unsupported mime type: ' + (($binary && $binary.data && $binary.data.mimeType) || 'unknown'), stage: 'file_type_check' } };

return { json: { registry_sheet_id: $json.registry_sheet_id, timestamp: $now.toISO(),
  google_drive_file_id: $json.google_drive_file_id || $json.id || '', source_document: $json.source_document || $json.name || 'unknown',
  error_type: 'pinecone_insert_failed', error_message: ($json.error && $json.error.message) || JSON.stringify($json).slice(0,300), stage: 'pinecone_insert' } };

return { json: { registry_sheet_id: $json.registry_sheet_id, timestamp: $now.toISO(),
  google_drive_file_id: $json.google_drive_file_id || $json.id || '', source_document: $json.source_document || $json.name || 'unknown',
  error_type: 'pinecone_delete_failed', error_message: ($json.error && $json.error.message) || JSON.stringify($json).slice(0,300), stage: 'pinecone_delete' } };

return { json: { registry_sheet_id: $json.registry_sheet_id, google_drive_file_id: $json.google_drive_file_id,
  source_document: $json.source_document, category: $json.category, file_type: $json.file_type,
  clinic_id: $json.clinic_id, clinic_name: $json.clinic_name, last_indexed: $now.toISO(), status: 'Active' } };

const matches = ($json.matches || []);
const ids = matches.map(m => m.id).filter(Boolean);
return { json: { ...$json, _vector_ids_to_delete: ids } };

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const cfg = $('Attach Clinic Config (Deletion Check)').first().json;
return [{ json: { current_file_ids: ids, registry_sheet_id: cfg.registry_sheet_id, pinecone_index: cfg.pinecone_index,
  pinecone_namespace: cfg.pinecone_namespace, pinecone_host: cfg.pinecone_host, embedding_dimension: cfg.embedding_dimension } }];

const meta = $('Collect Current File IDs').first().json;
const currentIds = meta.current_file_ids || [];
const rows = $input.all().map(i => i.json).filter(r => r && r.google_drive_file_id && (r.status || 'Active') !== 'Deleted');
const deleted = rows.filter(r => !currentIds.includes(r.google_drive_file_id));
return deleted.map(r => ({ json: {
  google_drive_file_id: r.google_drive_file_id, source_document: r.source_document || '',
  pinecone_index: meta.pinecone_index, pinecone_namespace: meta.pinecone_namespace, pinecone_host: meta.pinecone_host,
  embedding_dimension: meta.embedding_dimension, registry_sheet_id: meta.registry_sheet_id
} }));

const matches = ($json.matches || []);
const ids = matches.map(m => m.id).filter(Boolean);
return { json: { ...$json, _vector_ids_to_delete: ids } };
